      "keystrokes": "python3 << 'PYEOF'
import json

benchmark_task = {
    "task_id": "adv-prompt-001",
    "task_name": "Incident Response Analysis with Adversarial Methodology",
    "description": "Apply the adversarial prompting methodology to analyze a complex incident response scenario. The model must generate multiple solution approaches, rigorously critique each for weaknesses, develop fixes, validate those fixes, and consolidate into ranked recommendations. This tests the model's ability to perform deep adversarial analysis across multiple solution spaces while identifying failure modes and edge cases.",
    "difficulty": "hard",
    "category": "adversarial-prompting",
    "input_generation": {
        "script": "python3 gen_inputs.py",
        "description": "Generates deterministic test data including: case_notes.txt with incident details, structured_input.json with project markers and thread status, reference_brief.pdf with embedded markers, and manifest.txt with expected markers for validation.",
        "files": [
            "data/case_notes.txt",
            "data/structured_input.json",
            "data/reference_brief.pdf",
            "data/manifest.txt"
        ]
    },
    "prompt_template": {
        "system": "You are an expert incident response analyst using the adversarial prompting methodology. Apply a rigorous 7-phase process: (1) Solution Generation - produce 3-7 distinct approaches, (2) Adversarial Critique - identify critical weaknesses in each solution examining edge cases and failure modes, (3) Fix Development - create specific fixes addressing identified weaknesses, (4) Fix Validation - validate whether fixes adequately address the issues, (5) Consolidation - merge the best elements into cohesive recommendations, (6) Ranking - order solutions by effectiveness and risk, (7) Recommendation - provide a final actionable recommendation with confidence levels. Show your reasoning throughout each phase.",
        "user": "Analyze the following incident response scenario using the adversarial prompting methodology:\n\n--- INCIDENT DATA ---\n{case_notes}\n{structured_input}\n{pdf_brief}\n--- END INCIDENT DATA ---\n\nProduce a comprehensive markdown report that:\n1. Generates at least 4 distinct solution approaches for addressing the incident\n2. For each solution, provides adversarial critique identifying at least 3 specific weaknesses\n3. Develops concrete fixes for each identified weakness\n4. Validates whether each fix adequately addresses its corresponding weakness\n5. Consolidates findings into ranked recommendations\n6. Identifies all markers from the input data (MARKER_ALPHA, MARKER_BETA, MARKER_GAMMA, MARKER_PDF_DELTA)\n7. Provides a final recommendation with risk assessment and confidence level\n\nFormat your output as a structured markdown document with clear section headers for each phase."
    },
    "ground_truth": {
        "expected_markers": ["MARKER_ALPHA", "MARKER_BETA", "MARKER_GAMMA", "MARKER_PDF_DELTA"],
        "expected_phases": ["Solution Generation", "Adversarial Critique", "Fix Development", "Fix Validation", "Consolidation", "Ranking", "Recommendation"],
        "min_solutions": 4,
        "min_weaknesses_per_solution": 3,
        "expected_output_format": "markdown",
        "key_findings": [
            "Multiple distinct solution approaches must be presented",
            "Each solution must have critical weaknesses identified",
            "Fixes must directly address identified weaknesses",
            "Validation must assess fix adequacy",
            "Recommendations must be ranked by effectiveness/risk",
            "All input markers must be identified and referenced",
            "Final recommendation must include confidence level"
        ]
    },
    "grader": {
        "scoring_criteria": [
            {
                "criterion": "phase_completeness",
                "weight": 0.20,
                "description": "All 7 phases of adversarial methodology are present and clearly labeled",
                "max_score": 20
            },
            {
                "criterion": "solution_diversity",
                "weight": 0.15,
                "description": "At least 4 distinct solution approaches with different core strategies",
                "max_score": 15
            },
            {
                "criterion": "critique_depth",
                "weight": 0.20,
                "description": "Each solution has at least 3 specific weaknesses identified with edge case analysis",
                "max_score": 20
            },
            {
                "criterion": "fix_quality",
                "weight": 0.15,
                "description": "Fixes are concrete, actionable, and directly address identified weaknesses",
                "max_score": 15
            },
            {
                "criterion": "marker_identification",
                "weight": 0.10,
                "description": "All 4 markers from input data are correctly identified and referenced",
                "max_score": 10
            },
            {
                "criterion": "ranking_rationale",
                "weight": 0.10,
                "description": "Recommendations are ranked with clear rationale based on effectiveness and risk",
                "max_score": 10
            },
            {
                "criterion": "reasoning_visibility",
                "weight": 0.10,
                "description": "Reasoning and thinking process is visible throughout all phases",
                "max_score": 10
            }
        ],
        "total_score": 100,
        "passing_threshold": 70
    },
    "adversarial_aspects": [
        {
            "aspect": "solution_space_exploration",
            "description": "Tests whether the model explores diverse solution spaces rather than converging prematurely on a single approach",
            "attack_vector": "Models may default to the first plausible solution without exploring alternatives",
            "success_indicator": "Multiple genuinely distinct approaches with different core strategies"
        },
        {
            "aspect": "self_critique_rigor",
            "description": "Tests whether the model performs genuine adversarial self-critique rather than superficial acknowledgment of potential issues",
            "attack_vector": "Models may list generic weaknesses without deep analysis of specific failure modes",
            "success_indicator": "Specific, actionable weaknesses tied to concrete edge cases and failure scenarios"
        },
        {
            "aspect": "fix_validation_honesty",
            "description": "Tests whether the model honestly validates whether fixes actually work or acknowledges remaining gaps",
            "attack_vector": "Models may claim all fixes are adequate without genuine validation",
            "success_indicator": "Honest assessment of fix adequacy with acknowledgment of residual risks where appropriate"
        },
        {
            "aspect": "cross_source_synthesis",
            "description": "Tests ability to synthesize information across multiple input formats (txt, json, pdf)",
            "attack_vector": "Models may miss information in non-text formats or fail to cross-reference",
            "success_indicator": "All markers from all input sources correctly identified and integrated into analysis"
        }
    ],
    "evaluation_script": "#!/usr/bin/env python3\nimport json\nimport re\nimport sys\n\ndef evaluate(output, ground_truth):\n    score = 0\n    criteria_results = {}\n    \n    # Phase completeness (20 points)\n    phases = ['Solution Generation', 'Adversarial Critique', 'Fix Development', 'Fix Validation', 'Consolidation', 'Ranking', 'Recommendation']\n    phases_found = sum(1 for p in phases if p.lower() in output.lower())\n    phase_score = min(20, (phases_found / 7) * 20)\n    criteria_results['phase_completeness'] = {'score': phase_score, 'max': 20, 'details': f'Found {phases_found}/7 phases'}\n    score += phase_score\n    \n    # Solution diversity (15 points)\n    solution_patterns = [r'Solution [1-7]', r'Approach [1-7]', r'Option [1-7]', r'Strategy [1-7]']\n    solutions_found = 0\n    for pattern in solution_patterns:\n        matches = re.findall(pattern, output, re.IGNORECASE)\n        solutions_found = max(solutions_found, len(matches))\n    solution_score = min(15, (min(solutions_found, 4) / 4) * 15)\n    criteria_results['solution_diversity'] = {'score': solution_score, 'max': 15, 'details': f'Found {solutions_found} solutions'}\n    score += solution_score\n    \n    # Critique depth (20 points)\n    weakness_keywords = ['weakness', 'limitation', 'drawback', 'risk', 'failure', 'issue']\n    weakness_count = sum(1 for kw in weakness_keywords if kw in output.lower())\n    critique_score = min(20, (min(weakness_count, 12) / 12) * 20)\n    criteria_results['critique_depth'] = {'score': critique_score, 'max': 20, 'details': f'Found {weakness_count} weakness references'}\n    score += critique_score\n    \n    # Fix quality (15 points)\n    fix_keywords = ['fix', 'solution', 'address', 'mitigate', 'resolve']\n    fix_count = sum(1 for kw in fix_keywords if kw in output.lower())\n    fix_score = min(15, (min(fix_count, 10) / 10) * 15)\n    criteria_results['fix_quality'] = {'score': fix_score, 'max': 15, 'details': f'Found {fix_count} fix references'}\n    score += fix_score\n    \n    # Marker identification (10 points)\n    expected_markers = ground_truth['expected_markers']\n    markers_found = sum(1 for m in expected_markers if m in output)\n    marker_score = (markers_found / len(expected_markers)) * 10\n    criteria_results['marker_identification'] = {'score': marker_score, 'max': 10, 'details': f'Found {markers_found}/{len(expected_markers)} markers'}\n    score += marker_score\n    \n    # Ranking rationale (10 points)\n    ranking_keywords = ['rank', 'priority', 'order', 'recommendation', 'best']\n    ranking_count = sum(1 for kw in ranking_keywords if kw in output.lower())\n    ranking_score = min(10, (min(ranking_count, 5) / 5) * 10)\n    criteria_results['ranking_rationale'] = {'score': ranking_score, 'max': 10, 'details': f'Found {ranking_count} ranking references'}\n    score += ranking_score\n    \n    # Reasoning visibility (10 points)\n    reasoning_keywords = ['because', 'therefore', 'thus', 'reason', 'rationale', 'analysis']\n    reasoning_count = sum(1 for kw in reasoning_keywords if kw in output.lower())\n    reasoning_score = min(10, (min(reasoning_count, 10) / 10) * 10)\n    criteria_results['reasoning_visibility'] = {'score': reasoning_score, 'max': 10, 'details': f'Found {reasoning_count} reasoning references'}\n    score += reasoning_score\n    \n    return {\n        'total_score': score,\n        'max_score': 100,\n        'passed': score >= 70,\n        'criteria_results': criteria_results,\n        'feedback': f'Score: {score}/100. {\"PASSED\" if score >= 70 else \"FAILED\"}'\n    }\n\nif __name__ == '__main__':\n    with open('/workspace/benchmark_task.json', 'r') as f:\n        task = json.load(f)\n    if len(sys.argv) > 1:\n        with open(sys.argv[1], 'r') as f:\n            output = f.read()\n    else:\n        output = sys.stdin.read()\n    result = evaluate(output, task['ground_truth'])\n    print(json.dumps(result, indent=2))"
}

with open('/workspace/benchmark_task.json', 'w') as f:
    json.dump(benchmark_task, f, indent=2)

print('benchmark_task.json created successfully')
PYEOF
